public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    permuteHelper(nums, 0, result, new ArrayList<>());
    return result;
}

private void permuteHelper(int[] nums, int start, List<List<Integer>> result, List<Integer> current) {
    if (start == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        current.add(nums[i]);
        permuteHelper(nums, start + 1, result, current);
        current.remove(current.size() - 1);
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (String str : strings) {
        if (str.length() > maxLength) {
            maxLength = str.length();
        }
    }

    boolean found = false;

    while (found == false) {
        found = true;
        for (String str : strings) {
            if (str.length() != maxLength) {
                continue;
            }

            String reversedStr = new StringBuilder(str).reverse().toString();
            if (!str.contains(reversedStr) && !reversedStr.contains(str)) {
                maxLength--;
                found = false;
                break;
            }
        }
    }

    return maxLength;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int numRows = grid.length;
    int numCols = grid[0].length;
    boolean[][] visited = new boolean[numRows][numCols];
    int depositCount = 0;

    for (int row = 0; row < numRows; row++) {
        for (int col = 0; col < numCols; col++) {
            if (grid[row][col] == '@' && !visited[row][col]) {
                dfs(grid, visited, row, col);
                depositCount++;
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int numRows = grid.length;
    int numCols = grid[0].length;
    if (row < 0 || row >= numRows || col < 0 || col >= numCols || grid[row][col] == '*' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;
    dfs(grid, visited, row - 1, col); // up
    dfs(grid, visited, row + 1, col); // down
    dfs(grid, visited, row, col - 1); // left
    dfs(grid, visited, row, col + 1); // right
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }

    if (N == 0) {
        return 1; // No triangles, one region (the whole plane)
    }

    // Each new triangle can intersect with all previous triangles, adding new regions
    return 1 + 3 * (N - 1) + (N - 1) * (N - 2) / 2;
}

