public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    boolean[][] grid = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2) {
            throw new IllegalArgumentException("Invalid path format");
        }
        int x1 = path[0];
        int y1 = path[1];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n) {
            throw new IllegalArgumentException("Path coordinates out of bounds");
        }
        grid[x1][y1] = true;
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX < 0 || startX >= n || startY < 0 || startY >= n || !grid[startX][startY]) {
        return "cannot be travelled";
    }

    if (endX < 0 || endX >= n || endY < 0 || endY >= n || !grid[endX][endY]) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{startX, startY});
    visited[startX][startY] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == endX && y == endY) {
            return "can be travelled";
        }

        for (int[] dir : directions) {
            int newX = x + dir[0];
            int newY = y + dir[1];

            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY] && grid[newX][newY]) {
                queue.add(new int[]{newX, newY});
                visited[newX][newY] = true;
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input strings must not be null");
    }

    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();

    Set<Character> set1 = new HashSet<>();
    Set<Character> set2 = new HashSet<>();

    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    int commonCount = 0;

    for (char c : set1) {
        if (set2.contains(c)) {
            commonCount++;
        }
    }

    int totalLength = word1.length() + word2.length();

    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(commonCount, totalLength);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (totalLength / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

