public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    int[] remainderCounts = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainder
        remainderCounts[remainder]++;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false;
        }
    }

    return remainderCounts[0] % 2 == 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] tree = new List[n];
    for (int i = 0; i < n; i++) {
        tree[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        tree[edge[0]].add(edge[1]);
        tree[edge[1]].add(edge[0]);
    }
    return dfs(0, -1, hasApple, tree) * 2;
}

private int dfs(int node, int parent, boolean[] hasApple, List<Integer>[] tree) {
    int time = 0;
    for (int neighbor : tree[node]) {
        if (neighbor == parent) {
            continue;
        }
        int appleTime = dfs(neighbor, node, hasApple, tree);
        if (appleTime > 0 || hasApple[neighbor]) {
            time += appleTime + 2;
        }
    }
    return time;
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder(s.length());
    while (result.length() < s.length()) {
        // Step 1 to 3: Pick smallest characters
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }

        // Step 4 to 6: Pick largest characters
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] dp = new boolean[sum + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int j = sum; j >= num; j--) {
            dp[j] = dp[j] || dp[j - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (dp[sum * i / n] && sum * i % n == 0) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

