}

public int minOperations(int n) {
    int minOperations = 0;

    // Calculate the target value that all elements should be equal to
    int target = n;

    // Calculate the sum of the first n odd numbers
    int sumOfOdds = n * n;

    // The minimum operations required is half the difference between the sum of odd numbers and the target value times n
    minOperations = sumOfOdds - target * n;

    return minOperations / 2;
}

