}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    List<Integer> fibonacciNumbers = generateFibonacciNumbers(k);
    int count = 0;
    for (int i = fibonacciNumbers.size() - 1; k > 0; i--) {
        if (fibonacciNumbers.get(i) <= k) {
            k -= fibonacciNumbers.get(i);
            count++;
        }
    }
    return count;
}

private List<Integer> generateFibonacciNumbers(int k) {
    List<Integer> fib Numbers = new ArrayList<>();
    if (k >= 1) {
        fibNumbers.add(1);
    }
    if (k >= 2) {
        fibNumbers.add(1);
    }
    int a = 1, b = 1;
    while (b + a <= k) {
        int next = a + b;
        fibNumbers.add(next);
        a = b;
        b = next;
    }
    return fibNumbers;
}

