public static int countDigitOne(int n) {
    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long divider = i * 10;
        long curr = (n / divider) * i;
        long rest = n % divider;
        if (curr % i < i) {
            count += curr / i * i + Math.min(i, rest + 1);
        } else {
            count += curr / i * i + i;
        }
    }
    return count;
}

