}

public static int longestLine(final int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // directions: right, down, down-right, down-left
    int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                for (int[] direction : directions) {
                    int len = 1;
                    int x = i + direction[0];
                    int y = j + direction[1];

                    while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] == 1) {
                        len++;
                        x += direction[0];
                        y += direction[1];
                    }

                    longest = Math.max(longest, len);
                }
            }
        }
    }

    return longest;
}

