public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] count = new int[n];
    count[0] = 1;
    for (int i = 1; i < n; i++) {
        int sum = A[i - 1] + A[i];
        int sqrt = (int) Math.sqrt(sum);
        if (sqrt * sqrt == sum) {
            for (int j = i - 1; j >= 0; j--) {
                if (A[j] == A[i]) {
                    count[i] += count[j];
                }
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += count[i];
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;
    int i = 0;

    while (i < heights.length) {
        if (stack.isEmpty() || heights[stack.peek()] <= heights[i]) {
            stack.push(i++);
        } else {
            int topIndex = stack.pop();
            int height = heights[topIndex];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
    }

    while (!stack.isEmpty()) {
        int topIndex = stack.pop();
        int height = heights[topIndex];
        int width = stack.isEmpty() ? i : i - stack.peek() - 1;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Traverse upwards
            for (int i = Math.min(d, rows - 1); i >= Math.max(0, d - cols + 1); i--) {
                result[index++] = mat[i][d - i];
            }
        } else {
            // Traverse downwards
            for (int i = Math.max(0, d - cols + 1); i <= Math.min(d, rows - 1); i++) {
                result[index++] = mat[i][d - i];
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i;
    // Find the first digit that is smaller than the digit next to it.
    for (i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }
    // If no such digit is found, return -1.
    if (i == -1) {
        return -1;
    }
    // Find the smallest digit on the right side of digits[i] but larger than digits[i].
    int j;
    for (j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }
    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Sort the digits after the position i
    Arrays.sort(digits, i + 1, digits.length);
    // Convert the array back to integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    backtrack(result, new char[n], 0, n - 1);
    return result;
}

private static void backtrack(List<String> result, char[] current, int left, int right) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    char[] symmetricPairs = {'0', '1', '6', '8', '9'};
    for (int i = 0; i < symmetricPairs.length; i++) {
        if (left == right && symmetricPairs[i] != symmetricPairs[i] && symmetricPairs[i] != '0') {
            continue; // Skip '0' for single-digit numbers and symmetric pairs that are not valid center symmetric numbers
        }
        current[left] = symmetricPairs[i];
        if (left != right) {
            current[right] = symmetricPairs[i] == '6' ? '9' : (symmetricPairs[i] == '9' ? '6' : symmetricPairs[i]);
        }
        backtrack(result, current, left + 1, right - 1);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    if (points[0] == null || points[1] == null || points[2] == null) {
        return false;
    }
    if (points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int index2 = 0, index3 = 0, index5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int nextUglyNumber = 1;

    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            index2++;
            nextMultipleOf2 = uglyNumbers[index2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            index3++;
            nextMultipleOf3 = uglyNumbers[index3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            index5++;
            nextMultipleOf5 = uglyNumbers[index5] * 5;
        }
    }

    return nextUglyNumber;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
            maxEnergy = Math.max(maxEnergy, currentEnergy);
        } else {
            currentEnergy = 1;
        }
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            break;
        }
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    Map<Integer, Integer> frequencyMap = new HashMap<>();
    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }

    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Create an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Fill the array with a large number (infinity), except for the base case
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    // Zero can be represented by zero perfect squares
    dp[0] = 0;

    // Iterate through each number from 1 to n
    for (int i = 1; i <= n; i++) {
        // Check each perfect square smaller than or equal to i
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // Return the minimum number of perfect squares for n
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        result.append(reversedWord).append(" ");
    }

    if (result.length() > 0) {
        result.setLength(result.length() - 1);
    }

    return result.toString();
}
